def gen(rng):
    def fmt(a):
        return f"{len(a)}\n" + ' '.join(map(str, a))
    def rot(n):
        return list(range(2, n + 1)) + [1]
    tests = [fmt([1]), fmt([2, 1]), fmt([1, 2, 3]), fmt([4, 1, 2, 3]), fmt([3, 2, 1]),
             fmt([2, 1, 4, 3, 5]), fmt(list(range(7, 0, -1))), fmt(rot(7))]
    for n in (2, 3, 4, 5, 6, 7):
        for _ in range(2):
            a = list(range(1, n + 1))
            rng.shuffle(a)
            tests.append(fmt(a))
    for n in (20, 40, 60):
        a = list(range(1, n + 1))
        rng.shuffle(a)
        tests.append(fmt(a))
    N = 10**5
    a = list(range(1, N + 1)); rng.shuffle(a); tests.append(fmt(a))
    tests.append(fmt(rot(N)))
    tests.append(fmt(list(range(N, 0, -1))))
    tests.append(fmt(list(range(1, N + 1))))
    b = list(range(1, N + 1))
    for i in range(0, N - 1, 2):
        b[i], b[i + 1] = b[i + 1], b[i]
    tests.append(fmt(b))
    return tests
